import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Quick Start","description":"NitroCord in 60 seconds for existing Velocity users — swap the jar, add your license key, start. Plus the five protection.toml tweaks worth making first.","frontmatter":{"title":"Quick Start","description":"NitroCord in 60 seconds for existing Velocity users — swap the jar, add your license key, start. Plus the five protection.toml tweaks worth making first."},"headers":[],"relativePath":"nitrocord/getting-started/quick-start.md","filePath":"nitrocord/getting-started/quick-start.md","lastUpdated":1785341162000}'),n={name:"nitrocord/getting-started/quick-start.md"};function o(l,s,r,h,d,c){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>Already running Velocity? NitroCord is a drop-in fork: your <code>velocity.toml</code>, backends, forwarding secret and every Velocity plugin keep working unchanged. You can be protected in about 60 seconds.</p><h2 id="the-60-second-path" tabindex="-1">The 60-second path <a class="header-anchor" href="#the-60-second-path" aria-label="Permalink to &quot;The 60-second path&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Stop your Velocity proxy, then drop the NitroCord jar into the same directory.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Add your license key to nitrocord.toml (create the line if the file</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#    does not exist yet — it is generated on first start):</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#    license-key = &quot;PL-XXXX-XXXX-XXXX-XXXX&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Start NitroCord exactly like you started Velocity:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NitroCord-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-all.jar</span></span></code></pre></div><p>Done. When the console prints <code>License verified - thank you for supporting NitroCord.</code>, the full protection engine is live — attack mode, firewall, rate limiting, anti-bot checks, anti-VPN blocklists, packet flood scoring — all with tuned defaults. No other configuration is required.</p><div class="info custom-block"><p class="custom-block-title">New to Velocity entirely?</p><p>Follow the full <a href="/pingless-studios-docs/nitrocord/getting-started/installation">Installation</a> instead — it covers Java 25, the kernel firewall prerequisites and post-install verification.</p></div><h2 id="the-5-tweaks-worth-making-first" tabindex="-1">The 5 tweaks worth making first <a class="header-anchor" href="#the-5-tweaks-worth-making-first" aria-label="Permalink to &quot;The 5 tweaks worth making first&quot;">​</a></h2><p>Defaults are production-safe, but these five knobs in <code>protection.toml</code> are the ones most admins adjust to their network. Everything below is applied live with <code>/nitrocord reload</code> — no restart needed.</p><h3 id="_1-firewall-ban-duration" tabindex="-1">1. Firewall ban duration <a class="header-anchor" href="#_1-firewall-ban-duration" aria-label="Permalink to &quot;1. Firewall ban duration&quot;">​</a></h3><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">firewall</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ban-time-seconds = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span></span></code></pre></div><p>How long an IP stays firewalled after tripping protection. The 60-second default sheds drive-by bots; raise it (e.g. <code>300</code>–<code>600</code>) if the same sources keep coming back, or lower it on shared hosting where players sit behind carrier NAT.</p><h3 id="_2-attack-mode-sensitivity" tabindex="-1">2. Attack-mode sensitivity <a class="header-anchor" href="#_2-attack-mode-sensitivity" aria-label="Permalink to &quot;2. Attack-mode sensitivity&quot;">​</a></h3><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">attack</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">activate-connections-per-second = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">deactivate-delay-seconds = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span></span></code></pre></div><p>Attack mode engages when the proxy-wide connection rate exceeds 40/s and disengages after 60 quiet seconds. Big networks with legitimately high join rates should raise the threshold so normal traffic never escalates checks.</p><h3 id="_3-online-anti-vpn-checks" tabindex="-1">3. Online anti-VPN checks <a class="header-anchor" href="#_3-online-anti-vpn-checks" aria-label="Permalink to &quot;3. Online anti-VPN checks&quot;">​</a></h3><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">antivpn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">online-check = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">proxycheck-key = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">iphub-key = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span></code></pre></div><p>The seven offline blocklists are already active. Add a <a href="https://proxycheck.io/" target="_blank" rel="noreferrer">proxycheck.io</a> or <a href="https://iphub.info/" target="_blank" rel="noreferrer">IPHub</a> API key and set <code>online-check = true</code> to also query those providers for IPs the local lists miss. Results are cached per IP (<code>cache-minutes = 60</code>) and persisted across restarts.</p><h3 id="_4-country-blocking" tabindex="-1">4. Country blocking <a class="header-anchor" href="#_4-country-blocking" aria-label="Permalink to &quot;4. Country blocking&quot;">​</a></h3><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">country</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">maxmind-license-key = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">blacklist = []</span></span></code></pre></div><p>Disabled by default because it needs your own (free) <a href="https://www.maxmind.com/en/geolite2/signup" target="_blank" rel="noreferrer">MaxMind key</a>. Set the key, <code>enabled = true</code>, and add ISO 3166-1 alpha-2 codes to <code>blacklist</code> — e.g. <code>[&quot;CN&quot;, &quot;RU&quot;]</code> — to deny joins from those countries. The GeoLite2 database downloads and updates itself.</p><h3 id="_5-accounts-per-ip" tabindex="-1">5. Accounts per IP <a class="header-anchor" href="#_5-accounts-per-ip" aria-label="Permalink to &quot;5. Accounts per IP&quot;">​</a></h3><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">accounts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">limit = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">firewall-on-trigger = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><p>How many distinct nicknames one IP may join with before new ones are kicked — the classic bot-flood signature. Lower it to <code>2</code> if you are being hammered by name-generated floods; raise it for schools, cafés or households sharing one connection.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Every key is documented inline — <code>protection.toml</code> ships with a comment above each setting, and new keys from updates are merged into your file automatically. Read it once end to end; it is the whole protection engine on one page.</p></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/pingless-studios-docs/nitrocord/getting-started/installation">Installation</a> — prerequisites, kernel firewall, verification checklist, troubleshooting.</li><li><a href="/pingless-studios-docs/nitrocord/getting-started/licensing">Licensing</a> — seats, offline grace and what happens when the license server is unreachable.</li><li>Run <code>/nitrocord</code> in-game (permission <code>nitrocord.admin</code>) for <code>stats</code>, <code>reload</code> and manual <code>firewall add|remove &lt;ip&gt;</code>.</li></ul>`,26)])])}const g=e(n,[["render",o]]);export{k as __pageData,g as default};
